/** Host Promise operations for work that continues after project evaluation. */
import { primordialArraySet } from "./array.js";
export const IntrinsicPromise = Promise;
export const primordialPromiseResolve = Promise.resolve.bind(Promise);
export const primordialPromiseReject = Promise.reject.bind(Promise);
export async function primordialPromiseThen(promise, fulfilled, rejected) {
    let value;
    try {
        value = await promise;
    }
    catch (error) {
        if (rejected)
            return await rejected(error);
        throw error;
    }
    return fulfilled ? await fulfilled(value) : value;
}
export function primordialPromiseCatch(promise, rejected) {
    return primordialPromiseThen(promise, undefined, rejected);
}
export async function primordialPromiseFinally(promise, settled) {
    try {
        return await promise;
    }
    finally {
        await settled();
    }
}
export function primordialPromiseAll(values) {
    return new IntrinsicPromise((resolve, reject) => {
        const results = [];
        let remaining = 1;
        for (let index = 0; index < values.length; index++) {
            const value = values[index];
            remaining++;
            void (async () => {
                try {
                    primordialArraySet(results, index, await value);
                    if (--remaining === 0)
                        resolve(results);
                }
                catch (error) {
                    reject(error);
                }
            })();
        }
        if (--remaining === 0)
            resolve(results);
    });
}
export function primordialPromiseAllSettled(values) {
    const settled = [];
    for (let index = 0; index < values.length; index++) {
        const value = values[index];
        primordialArraySet(settled, index, (async () => {
            try {
                return { status: "fulfilled", value: await value };
            }
            catch (reason) {
                return { status: "rejected", reason };
            }
        })());
    }
    return primordialPromiseAll(settled);
}
